mapper.insert:
INSERT INTO users (username, email, password, phone, profile_image, role, status, refresh)
VALUES (#{username}, #{email}, #{password}, #{phone}, #{profileImage}, 
        'USER'#{role}, 
        'ACTIVE'#{status},
        #{refreshToken}
)

mapper.select:
SELECT user_id, username, email, phone, profile_image, role, status, created_at, updated_at, refresh
FROM users
WHERE user_id = #{userId}

mapper.update:
UPDATE users
username = #{username}, password = #{password}, phone = #{phone}, profile_image = #{profileImage}, role = #{role}, status = #{status}, refresh = #{refreshToken}, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}
